const newItems = [];

for (const item of $input.all()) {
  const job = item.json;

  // تغطية كل الاحتمالات الشائعة لأسماء المفاتيح من Apify/LinkedIn
  const companyName = job.companyName || job.company || job.company_name || "Needs manual review";
  const jobTitle = job.title || job.jobTitle || job.position || "New Job Posting";
  const jobUrl = job.link || job.url || job.jobUrl;
  const postDate = job.postedAt || job.date || new Date().toISOString();

  newItems.push({
    json: {
      company_name: companyName,
      domain: null, 
      signal_type: "Hiring",
      detected_date: postDate,
      evidence_description: jobTitle,
      evidence_url: jobUrl
    }
  });
}

return newItems;

const newItems = [];

for (const item of $input.all()) {
  const rawTitle = item.json.title || '';

  // تنظيف اسم المصدر في نهاية العنوان
  const cleanTitle = rawTitle.replace(/\s*-\s*[A-Za-z .]+$/, '').trim();

  let companyName = null;

  // تحديث الأنماط لتشمل الحالات الإخبارية العامة
  const patterns = [
    // 1. البحث عن كلمات التمويل المباشرة
    /([A-Z][\w&.-]*(?:\s+[A-Z][\w&.-]*){0,2})\s+(?:raises|secures|closes|lands|nets|bags|scores|gets)/i,
    // 2. البحث عن كلمة شركة أو شركة ناشئة
    /(?:startup|company)\s+([A-Z][\w&.-]*(?:\s+[A-Z][\w&.-]*){0,2})/i,
    // 3. (النمط الجديد) سحب أول كلمة أو كلمتين تبدأ بحرف كبير في بداية العنوان
    /^([A-Z][\w&.-]+(?:\s+[A-Z][\w&.-]+)?)/
  ];

  for (const re of patterns) {
    const m = cleanTitle.match(re);
    if (m && m[1]) { 
        companyName = m[1].trim(); 
        break; 
    }
  }

  if (!companyName) companyName = 'Needs manual review';

  newItems.push({
    json: {
      company_name: companyName,
      domain: null, 
      signal_type: 'Funding',
      detected_date: item.json.isoDate, 
      evidence_description: cleanTitle, 
      evidence_url: item.json.link
    }
  });
}

return newItems;

const newItems = [];

for (const item of $input.all()) {
  // التعديل الجذري هنا: قراءة البيانات من body إن وجد، أو من الجذر المباشر للـ json
  const payload = item.json.body || item.json || {};

  const companyName = payload.company_name || payload.company || 'Needs manual review';
  const domain = payload.domain || payload.website || null; 

  const jobTitle = payload.job_title || payload.role || 'New position';
  const evidenceDescription = `Hiring for: ${jobTitle}`;

  const evidenceUrl = payload.url || payload.job_url || payload.link || '';

  const detectedDate = payload.timestamp || new Date().toISOString();

  newItems.push({
    json: {
      company_name: companyName,
      domain: domain, 
      signal_type: 'Hiring',
      detected_date: detectedDate,
      evidence_description: evidenceDescription,
      evidence_url: evidenceUrl
    }
  });
}

return newItems;

